import be.seeseemelk.mockbukkit.MockBukkit;
import me.rakkoon69.rakunloots.command.SenderLocation;
import me.rakkoon69.rakunloots.config.ConfigLoader;
import me.rakkoon69.rakunloots.config.ConfigSnapshot;
import me.rakkoon69.rakunloots.config.ConfigSources;
import me.rakkoon69.rakunloots.items.ItemSourceRegistry;
import me.rakkoon69.rakunloots.menu.MenuRenderer;
import me.rakkoon69.rakunloots.menu.MenuService;
import me.rakkoon69.rakunloots.menu.MenuWarnings;
import me.rakkoon69.rakunloots.server.LoadedWorld;
import me.rakkoon69.rakunloots.server.ServerAdapter;
import me.rakkoon69.rakunloots.storage.StreamableServerMock;
import me.rakkoon69.rakunloots.summon.FakeServerAdapter;
import me.rakkoon69.rakunloots.wiki.LootChanceCache;
import me.rakkoon69.rakunloots.wiki.WikiMenu;

import java.lang.reflect.InvocationTargetException;
import java.lang.reflect.Proxy;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.UUID;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.atomic.AtomicInteger;

final class ReproInverseOpenRace {
    private static final UUID WORLD = UUID.fromString("00000000-0000-0000-0000-00000000c1a8");
    private static final String LANGUAGE = """
            prefix: ""
            menu_wiki_list_title: "&8Loots wiki"
            menu_wiki_list_entry_name: "&e{loot}"
            menu_wiki_list_entry_lore:
              - "&7{description}"
            menu_wiki_list_timer_chance: "&7Chance: &e{chance:2}%"
            menu_wiki_list_not_on_timer: "&7No timer"
            menu_wiki_list_click: "&eClick"
            menu_wiki_loot_title: "&8Loot {loot}"
            menu_wiki_content_chance: "&7Chance: &e{chance:2}%"
            menu_wiki_content_always: "&7Always included"
            menu_wiki_content_calculating: "&7Chance: calculating"
            menu_wiki_content_amount: "&7Amount: &e{amount}"
            menu_wiki_content_missing_name: "&cMissing {item}"
            menu_wiki_content_missing_lore:
              - "&7That item is not loaded."
            menu_wiki_info_name: "&6{loot} info"
            menu_wiki_info_open_mode: "&7Open mode: &e{open_mode}"
            menu_wiki_open_mode_drop: "&edrop"
            menu_wiki_open_mode_inventory: "&einventory"
            menu_wiki_info_lock: "&7Lock: &e{lock}"
            menu_wiki_info_no_lock: "&7Lock: &aNo lock"
            menu_wiki_info_life: "&7Life: &e{life}"
            menu_wiki_info_unending: "&7Life: &aUnending"
            menu_wiki_info_items: "&7Items: &e{min}&7 to &e{max}"
            menu_wiki_info_worlds: "&7Worlds:"
            menu_wiki_info_world: "&8- &e{world}&7: &e{chance:2}%"
            menu_wiki_info_no_worlds: "&7No world timer summons this loot."
            menu_button_back_name: "&a[Back]"
            menu_button_back_lore:
              - "&7Back to the list"
            """;
    private static final String WIKI_MENU = """
            list:
              rows: 2
              content_slots: ["0-8"]
              filler:
                id: stone
            loot:
              rows: 2
              content_slots: ["0-8"]
              filler:
                id: stone
              buttons:
                back:
                  slot: 9
                  item:
                    id: oak_door
                info:
                  slot: 10
                  item:
                    id: book
            """;

    public static void main(String[] args) {
        StreamableServerMock.mock();
        try {
            UUID player = UUID.randomUUID();
            FakeServerAdapter delegate = new FakeServerAdapter(WORLD);
            delegate.addOnlinePlayer(player);
            delegate.holdAsync();
            delegate.holdMenuOpens();
            CompletableFuture<List<LoadedWorld>> heldWorlds = new CompletableFuture<>();
            AtomicInteger reads = new AtomicInteger();
            ServerAdapter adapter = (ServerAdapter) Proxy.newProxyInstance(ServerAdapter.class.getClassLoader(),
                    new Class<?>[]{ServerAdapter.class}, (proxy, method, methodArgs) -> {
                        if (method.getName().equals("loadedWorlds") && reads.getAndIncrement() == 1) {
                            return heldWorlds;
                        }
                        try {
                            return method.invoke(delegate, methodArgs);
                        } catch (InvocationTargetException failure) {
                            throw failure.getCause();
                        }
                    });
            ConfigSnapshot config = ConfigLoader.load(ConfigSources.builder()
                    .globals("language: en\nbanned_loot_blocks: []\n")
                    .worlds("{}")
                    .language("en", LANGUAGE)
                    .menu("wiki", WIKI_MENU)
                    .loot("demo", "display_name: Demo\nopen_mode: drop\nblock: barrel\n"
                            + "roll:\n  entries:\n    a:\n      item:\n        id: diamond\n")
                    .build(), id -> Optional.of(id));
            ItemSourceRegistry items = ItemSourceRegistry.create();
            LootChanceCache cache = new LootChanceCache(delegate.async());
            MenuRenderer renderer = new MenuRenderer(items, key -> config.message("", key), MenuWarnings.ignore);
            MenuService menus = new MenuService(adapter, renderer);
            WikiMenu wiki = new WikiMenu(adapter, () -> config, items, menus, renderer, cache, (w, c) -> {});
            cache.load(config);
            SenderLocation location = new SenderLocation(WORLD, 0, 64, 0);

            wiki.open(player, location);
            wiki.open(player, location);
            delegate.releaseMenuOpens();
            if (delegate.menuOpens().size() != 1) {
                throw new AssertionError("the first open did not land");
            }
            heldWorlds.complete(List.of(new LoadedWorld(WORLD, "world")));
            if (delegate.menuOpens().size() != 1) {
                throw new AssertionError("the stale second open unexpectedly landed");
            }

            menus.click(player, 0).join();
            if (delegate.menuOpens().size() != 2) {
                throw new AssertionError("the visible list did not open its loot page");
            }
            int updates = delegate.menuUpdates().size();
            delegate.releaseAsync();

            if (delegate.menuUpdates().size() == updates) {
                throw new AssertionError("the current session was not registered, so the loot page never refreshed");
            }
            System.out.println("PASS");
        } finally {
            MockBukkit.unmock();
        }
    }
}
